import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.jit
def swizzle_tile(
    tile_id,
    M,
    N,
    K,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
):
    grid_m = tl.cdiv(M, BLOCK_M)
    grid_n = tl.cdiv(N, BLOCK_N)
    width = GROUP_SIZE_M * grid_n
    group_id = tile_id // width
    group_size = tl.minimum(GROUP_SIZE_M, grid_m - group_id * GROUP_SIZE_M)
    pid_m = group_id * GROUP_SIZE_M + (tile_id % group_size)
    pid_n = (tile_id % width) // group_size
    return pid_m, pid_n


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_M": 32, "BLOCK_N": 32, "BLOCK_K": 32, "GROUP_SIZE_M": 4},
        ),
    ],
    key=["M", "N", "K"],
)
@triton.jit
def conv2d_implicit_gemm_kernel(
    x_ptr,
    w_ptr,
    bias_ptr,
    out_ptr,
    M,
    N,
    K,
    OH,
    OW,
    H,
    W,
    stride_conv_h,
    stride_conv_w,
    pad_h,
    pad_w,
    stride_xn,
    stride_xc,
    stride_xh,
    stride_xw,
    stride_on,
    stride_oc,
    stride_oh,
    stride_ow,
    stride_wk,
    stride_wn: tl.constexpr,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
    KH: tl.constexpr,
    KW: tl.constexpr,
    C_IN: tl.constexpr,
):
    pid = tl.program_id(0)
    pid_m, pid_n = swizzle_tile(pid, M, N, K, BLOCK_M, BLOCK_N, BLOCK_K, GROUP_SIZE_M)

    offs_m = pid_m * BLOCK_M + tl.arange(0, BLOCK_M)
    offs_n = pid_n * BLOCK_N + tl.arange(0, BLOCK_N)

    ohow = OH * OW
    n_idx = (offs_m // ohow).to(tl.int64)
    rem = offs_m % ohow
    oh_idx = rem // OW
    ow_idx = rem % OW

    mask_m = offs_m < M
    mask_n = offs_n < N

    w_desc = tl.make_tensor_descriptor(
        base=w_ptr,
        shape=(K, N),
        strides=(stride_wk, stride_wn),
        block_shape=(BLOCK_K, BLOCK_N),
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)

    for k0 in range(0, K, BLOCK_K):
        offs_k = k0 + tl.arange(0, BLOCK_K)

        kh = offs_k // (KW * C_IN)
        kw = (offs_k // C_IN) % KW
        cin = offs_k % C_IN

        ih = oh_idx[:, None] * stride_conv_h + kh[None, :] - pad_h
        iw = ow_idx[:, None] * stride_conv_w + kw[None, :] - pad_w

        valid = (ih >= 0) & (ih < H) & (iw >= 0) & (iw < W) & (offs_k[None, :] < K)
        valid = valid & mask_m[:, None]

        x_ptrs = (
            x_ptr
            + n_idx[:, None] * stride_xn
            + cin[None, :].to(tl.int64) * stride_xc
            + ih.to(tl.int64) * stride_xh
            + iw.to(tl.int64) * stride_xw
        )

        x_tile = tl.load(x_ptrs, mask=valid, other=0.0)
        w_tile = w_desc.load([k0, pid_n * BLOCK_N])

        acc = tl.dot(x_tile, w_tile, acc)
    bias_vals = tl.load(bias_ptr + offs_n, mask=mask_n, other=0.0)
    acc += bias_vals[None, :]

    out_ptrs = (
        out_ptr
        + n_idx[:, None] * stride_on
        + offs_n[None, :].to(tl.int64) * stride_oc
        + oh_idx[:, None].to(tl.int64) * stride_oh
        + ow_idx[:, None].to(tl.int64) * stride_ow
    )
    tl.store(out_ptrs, acc.to(tl.bfloat16), mask=mask_m[:, None] & mask_n[None, :])


class Model(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        self.conv1 = nn.Conv2d(
            in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2
        )
        self._packed = False

    def _pack_weights(self):
        w = self.conv1.weight.data
        b = self.conv1.bias.data
        device = w.device
        self.w_packed = (
            w.permute(2, 3, 1, 0)
            .contiguous()
            .reshape(-1, w.shape[0])
            .to(device=device, dtype=torch.bfloat16)
            .contiguous()
        )
        self.bias_packed = b.to(device=device, dtype=torch.bfloat16).contiguous()
        self._packed = True

    def forward(self, x):
        if not self._packed:
            self._pack_weights()

        x = x.to(dtype=torch.bfloat16).contiguous()

        N_batch, C_in, H, W_in = x.shape
        C_out = self.w_packed.shape[1]
        KH, KW = 11, 11
        stride_h, stride_w = 4, 4
        pad_h, pad_w = 2, 2
        OH = (H + 2 * pad_h - KH) // stride_h + 1
        OW = (W_in + 2 * pad_w - KW) // stride_w + 1

        M = N_batch * OH * OW
        N = C_out
        K = C_in * KH * KW

        output = torch.empty(
            (N_batch, C_out, OH, OW), device=x.device, dtype=torch.bfloat16
        )

        grid = lambda META: (
            triton.cdiv(M, META["BLOCK_M"]) * triton.cdiv(N, META["BLOCK_N"]),
        )

        conv2d_implicit_gemm_kernel[grid](
            x,
            self.w_packed,
            self.bias_packed,
            output,
            M,
            N,
            K,
            OH,
            OW,
            H,
            W_in,
            stride_h,
            stride_w,
            pad_h,
            pad_w,
            x.stride(0),
            x.stride(1),
            x.stride(2),
            x.stride(3),
            output.stride(0),
            output.stride(1),
            output.stride(2),
            output.stride(3),
            self.w_packed.stride(0),
            self.w_packed.stride(1),
            KH=KH,
            KW=KW,
            C_IN=C_in,
        )

        return output


batch_size = 256
num_classes = 1000


def get_inputs():
    return [torch.rand(batch_size, 3, 224, 224, dtype=torch.bfloat16)]


def get_init_inputs():
    return [num_classes]
